CREATE TABLE person ( id TEXT PRIMARY KEY, haushalt_id TEXT REFERENCES haushalt(id), vorname TEXT NOT NULL, nachname TEXT NOT NULL, geburtsdatum TEXT, geschlecht TEXT, strasse TEXT, plz TEXT, ort TEXT, email TEXT, telefon TEXT, mobil TEXT, gateway_username TEXT, zusatz_json TEXT, bemerkung TEXT, anonymisiert_am TEXT, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL, geaendert_am TEXT, geaendert_von TEXT ); CREATE TABLE haushalt ( id TEXT PRIMARY KEY, bezeichnung TEXT, zahler_person_id TEXT REFERENCES person(id), abw_empfaenger TEXT, abw_strasse TEXT, abw_plz TEXT, abw_ort TEXT, zahlungsweise TEXT NOT NULL DEFAULT 'jaehrlich', zahlungsart TEXT NOT NULL DEFAULT 'lastschrift', erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL, geaendert_am TEXT, geaendert_von TEXT ); CREATE TABLE sparte ( id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, kurz TEXT, sortierung INTEGER NOT NULL DEFAULT 100, aktiv INTEGER NOT NULL DEFAULT 1, zuschlag_cent INTEGER NOT NULL DEFAULT 0, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL, geaendert_am TEXT, geaendert_von TEXT ); CREATE TABLE mitgliedschaft ( id TEXT PRIMARY KEY, person_id TEXT NOT NULL REFERENCES person(id), mitgliedsnummer TEXT NOT NULL UNIQUE, art TEXT NOT NULL, eintritt TEXT NOT NULL, austritt TEXT, austritt_grund TEXT, kuendigung_am TEXT, status TEXT NOT NULL DEFAULT 'aktiv', beschluss_am TEXT, beschluss_von TEXT, ermaessigt INTEGER NOT NULL DEFAULT 0, ermaessigt_grund TEXT, nachweis_geprueft_am TEXT, nachweis_gueltig_bis TEXT, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL, geaendert_am TEXT, geaendert_von TEXT ); CREATE TABLE mitgliedschaft_sparte ( id TEXT PRIMARY KEY, mitgliedschaft_id TEXT NOT NULL REFERENCES mitgliedschaft(id), sparte_id TEXT NOT NULL REFERENCES sparte(id), eintritt TEXT NOT NULL, austritt TEXT, zuschlag_cent INTEGER, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL, geaendert_am TEXT, geaendert_von TEXT ); CREATE TABLE beitragsklasse ( id TEXT PRIMARY KEY, name TEXT NOT NULL, alter_von INTEGER, alter_bis INTEGER, mitgliedsart TEXT, nur_ermaessigt INTEGER NOT NULL DEFAULT 0, sortierung INTEGER NOT NULL DEFAULT 100, aktiv INTEGER NOT NULL DEFAULT 1, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL ); CREATE TABLE beitragssatz ( id TEXT PRIMARY KEY, beitragsklasse_id TEXT NOT NULL REFERENCES beitragsklasse(id), gueltig_ab TEXT NOT NULL, gueltig_bis TEXT, betrag_cent INTEGER NOT NULL, beschluss_am TEXT, beschluss_notiz TEXT, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL ); CREATE TABLE familienrabatt ( id TEXT PRIMARY KEY, ab_anzahl INTEGER NOT NULL, prozent INTEGER, betrag_cent INTEGER, gueltig_ab TEXT NOT NULL, gueltig_bis TEXT, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL ); CREATE TABLE sepa_mandat ( id TEXT PRIMARY KEY, haushalt_id TEXT NOT NULL REFERENCES haushalt(id), referenz TEXT NOT NULL UNIQUE, kontoinhaber TEXT NOT NULL, iban TEXT NOT NULL, bic TEXT, erteilt_am TEXT NOT NULL, quelle TEXT NOT NULL DEFAULT 'papier', unterschrift_datei TEXT, signatur_ip TEXT, signatur_agent TEXT, bestaetigung_gesendet_am TEXT, erste_nutzung_am TEXT, letzte_nutzung_am TEXT, widerrufen_am TEXT, widerruf_grund TEXT, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL, geaendert_am TEXT, geaendert_von TEXT ); CREATE TABLE beitragslauf ( id TEXT PRIMARY KEY, bezeichnung TEXT NOT NULL, jahr INTEGER NOT NULL, periode TEXT NOT NULL, stichtag TEXT NOT NULL, faelligkeit TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'entwurf', fortschritt_ab TEXT, anzahl_erwartet INTEGER, anzahl_erzeugt INTEGER NOT NULL DEFAULT 0, summe_cent INTEGER NOT NULL DEFAULT 0, festgeschrieben_am TEXT, festgeschrieben_von TEXT, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL ); CREATE TABLE forderung ( id TEXT PRIMARY KEY, beitragslauf_id TEXT REFERENCES beitragslauf(id), mitgliedschaft_id TEXT NOT NULL REFERENCES mitgliedschaft(id), haushalt_id TEXT NOT NULL REFERENCES haushalt(id), art TEXT NOT NULL DEFAULT 'beitrag', bezeichnung TEXT NOT NULL, jahr INTEGER NOT NULL, periode TEXT, betrag_cent INTEGER NOT NULL, faellig_am TEXT NOT NULL, berechnung_json TEXT, status TEXT NOT NULL DEFAULT 'offen', storniert_am TEXT, storniert_von TEXT, storno_grund TEXT, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL ); CREATE TABLE sepa_datei ( id TEXT PRIMARY KEY, beitragslauf_id TEXT REFERENCES beitragslauf(id), msg_id TEXT NOT NULL UNIQUE, erstellt_datum TEXT NOT NULL, ausfuehrung_am TEXT NOT NULL, seq_typ TEXT NOT NULL, anzahl_posten INTEGER NOT NULL, summe_cent INTEGER NOT NULL, datei_pfad TEXT, eingereicht_am TEXT, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL ); CREATE TABLE zahlung ( id TEXT PRIMARY KEY, forderung_id TEXT REFERENCES forderung(id), haushalt_id TEXT NOT NULL REFERENCES haushalt(id), sepa_datei_id TEXT REFERENCES sepa_datei(id), betrag_cent INTEGER NOT NULL, eingang_am TEXT NOT NULL, art TEXT NOT NULL, verwendungszweck TEXT, ruecklauf_grund TEXT, ruecklauf_entgelt_cent INTEGER, storniert_am TEXT, storniert_von TEXT, storno_grund TEXT, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL ); CREATE TABLE mahnung ( id TEXT PRIMARY KEY, haushalt_id TEXT NOT NULL REFERENCES haushalt(id), mitgliedschaft_id TEXT REFERENCES mitgliedschaft(id), stufe INTEGER NOT NULL, erstellt_datum TEXT NOT NULL, frist_bis TEXT NOT NULL, summe_cent INTEGER NOT NULL, forderungen_json TEXT, versand_art TEXT NOT NULL DEFAULT 'brief', versendet_am TEXT, versendet_von TEXT, datei_pfad TEXT, erledigt_am TEXT, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL ); CREATE TABLE aufnahmeantrag ( id TEXT PRIMARY KEY, eingang_am TEXT NOT NULL, antrag_json TEXT NOT NULL, sparten_json TEXT, unterschrift_datei TEXT, unterschrift_gesetzl_datei TEXT, signatur_ip TEXT, signatur_agent TEXT, signatur_zeit TEXT, status TEXT NOT NULL DEFAULT 'neu', geprueft_am TEXT, geprueft_von TEXT, beschluss_am TEXT, ablehnung_grund TEXT, person_id TEXT REFERENCES person(id), mitgliedschaft_id TEXT REFERENCES mitgliedschaft(id) ); CREATE TABLE benutzer_rolle ( id TEXT PRIMARY KEY, username TEXT NOT NULL, rolle TEXT NOT NULL, sparte_id TEXT REFERENCES sparte(id), erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL ); CREATE TABLE protokoll ( id TEXT PRIMARY KEY, zeit TEXT NOT NULL, username TEXT, aktion TEXT NOT NULL, objekt_typ TEXT, objekt_id TEXT, detail_json TEXT ); CREATE INDEX idx_person_name ON person(nachname, vorname); CREATE INDEX idx_person_haushalt ON person(haushalt_id); CREATE INDEX idx_person_gateway ON person(gateway_username); CREATE INDEX idx_mgs_person ON mitgliedschaft(person_id); CREATE INDEX idx_mgs_status ON mitgliedschaft(status); CREATE INDEX idx_mgs_eintritt ON mitgliedschaft(eintritt); CREATE INDEX idx_mgspa_sparte ON mitgliedschaft_sparte(sparte_id, austritt); CREATE INDEX idx_mgspa_mgs ON mitgliedschaft_sparte(mitgliedschaft_id); CREATE INDEX idx_ford_haushalt ON forderung(haushalt_id, status); CREATE INDEX idx_ford_mgs ON forderung(mitgliedschaft_id); CREATE INDEX idx_ford_offen ON forderung(status, faellig_am); CREATE INDEX idx_zahlung_haushalt ON zahlung(haushalt_id, eingang_am); CREATE INDEX idx_zahlung_forderung ON zahlung(forderung_id); CREATE INDEX idx_mandat_haushalt ON sepa_mandat(haushalt_id, widerrufen_am); CREATE INDEX idx_mahnung_haushalt ON mahnung(haushalt_id, erledigt_am); CREATE INDEX idx_antrag_status ON aufnahmeantrag(status, eingang_am); CREATE INDEX idx_rolle_username ON benutzer_rolle(username); CREATE INDEX idx_protokoll_zeit ON protokoll(zeit); CREATE INDEX idx_protokoll_objekt ON protokoll(objekt_typ, objekt_id); CREATE UNIQUE INDEX idx_ford_lauf_eindeutig ON forderung(beitragslauf_id, mitgliedschaft_id, art) WHERE beitragslauf_id IS NOT NULL; CREATE UNIQUE INDEX idx_mandat_aktiv ON sepa_mandat(haushalt_id) WHERE widerrufen_am IS NULL; CREATE UNIQUE INDEX idx_mgspa_aktiv ON mitgliedschaft_sparte(mitgliedschaft_id, sparte_id) WHERE austritt IS NULL; CREATE TABLE geschaeftsjahr ( id TEXT PRIMARY KEY, jahr INTEGER NOT NULL UNIQUE, beginn TEXT NOT NULL, ende TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'offen', abgeschlossen_am TEXT, abgeschlossen_von TEXT, ergebnis_json TEXT, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL ); CREATE TABLE konto ( id TEXT PRIMARY KEY, nummer TEXT NOT NULL UNIQUE, name TEXT NOT NULL, art TEXT NOT NULL, sphaere TEXT, gruppe TEXT, aktiv INTEGER NOT NULL DEFAULT 1, sortierung INTEGER NOT NULL DEFAULT 100, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL ); CREATE TABLE geschaeftsvorfall_vorlage ( id TEXT PRIMARY KEY, name TEXT NOT NULL, erklaerung TEXT NOT NULL, soll_nummer TEXT NOT NULL, haben_nummer TEXT NOT NULL, sphaere TEXT, sortierung INTEGER NOT NULL DEFAULT 100, aktiv INTEGER NOT NULL DEFAULT 1, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL ); CREATE TABLE buchung ( id TEXT PRIMARY KEY, geschaeftsjahr_id TEXT NOT NULL REFERENCES geschaeftsjahr(id), belegnummer INTEGER NOT NULL, belegdatum TEXT NOT NULL, buchungsdatum TEXT NOT NULL, text TEXT NOT NULL, vorlage_id TEXT REFERENCES geschaeftsvorfall_vorlage(id), summe_cent INTEGER NOT NULL, art TEXT NOT NULL DEFAULT 'normal', quelle_typ TEXT, quelle_id TEXT, storniert_am TEXT, storniert_von TEXT, storno_von_id TEXT REFERENCES buchung(id), storno_grund TEXT, erstellt_am TEXT NOT NULL, erstellt_von TEXT NOT NULL ); CREATE TABLE buchungszeile ( id TEXT PRIMARY KEY, buchung_id TEXT NOT NULL REFERENCES buchung(id), konto_id TEXT NOT NULL REFERENCES konto(id), soll_cent INTEGER NOT NULL DEFAULT 0, haben_cent INTEGER NOT NULL DEFAULT 0, sphaere TEXT, sparte_id TEXT REFERENCES sparte(id), text TEXT ); CREATE UNIQUE INDEX idx_buchung_beleg ON buchung(geschaeftsjahr_id, belegnummer); CREATE UNIQUE INDEX idx_buchung_quelle ON buchung(quelle_typ, quelle_id) WHERE quelle_typ IS NOT NULL; CREATE INDEX idx_buchung_jahr ON buchung(geschaeftsjahr_id, belegdatum); CREATE INDEX idx_bzeile_buchung ON buchungszeile(buchung_id); CREATE INDEX idx_bzeile_konto ON buchungszeile(konto_id);